<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\Tourism\Services\TourismRoomService;use RuntimeException;use Throwable;
final class TourismRoomController extends Controller{private TourismRoomService $s;private Authorization $a;public function __construct(){$this->s=new TourismRoomService();$this->a=new Authorization();}private function allow(string $p,string $r):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function store(int $stayId):void{if(!$this->allow('tourism.rooms.manage','/tourism/stays/'.$stayId))return;try{$this->s->store((int)Auth::tenantId(),$stayId,$_POST,(int)Auth::id());flash('success','Room type added.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays/'.$stayId);}public function update(int $stayId,int $roomId):void{if(!$this->allow('tourism.rooms.manage','/tourism/stays/'.$stayId))return;try{$this->s->update((int)Auth::tenantId(),$stayId,$roomId,$_POST,(int)Auth::id());flash('success','Room type updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays/'.$stayId);}public function destroy(int $stayId,int $roomId):void{if(!$this->allow('tourism.rooms.manage','/tourism/stays/'.$stayId))return;try{$this->s->delete((int)Auth::tenantId(),$stayId,$roomId,(int)Auth::id());flash('success','Room type moved to Trash.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays/'.$stayId);}public function restore(int $stayId,int $roomId):void{if(!$this->allow('tourism.rooms.manage','/tourism/stays/'.$stayId))return;try{$this->s->restore((int)Auth::tenantId(),$stayId,$roomId,(int)Auth::id());flash('success','Room type restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays/'.$stayId);}}
